    public function test_json_compare(): void
    {
        // @Arrange
        $one = new TrustedClient(
            uid: 'one',
            code: 'one',
            allowAllScopes: true,
            publicAllow: true,
            allowedRedirects: new TrustedClientAllowedRedirectsListRef(new TrustedClientAllowedRedirectsItem(
