    public function test_enable_modify(): void
    {
        // @Arrange
        $source = new TrustedClient(
            uid: 'one',
            code: 'one',
            allowAllScopes: true,
            publicAllow: true,
            allowedRedirects: new TrustedClientAllowedRedirectsListRef(new TrustedClientAllowedRedirectsItem(
                TrustedClientAllowedRedirectsUidVO::from('one'),
                TrustedClientAllowedRedirectsUrlVO::from('one'),
                TrustedClientAllowedRedirectsVersionVO::from(1)
            )),
            secretOauth: 'cyphered://cypher',
            backChannelLogoutUri: 'one',
            backChannelLogoutSessionRequired: true,
            frontChannelLogoutUri: 'one',
            frontChannelLogoutSessionRequired: true,
            enabled: true,
            registrationAccess: 'one',
            clientName: 'one',
            logoUri: 'one',
            clientUri: 'one',
            policyUri: 'one',
            tosUri: 'one',
            tokenEndpointAuthMethod: 'one',
            grantTypesJson: 'one',
            responseTypesJson: 'one',
            dynamicallyRegistered: true,
            registeredAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            allowedScopesM2m: 'one',
            m2mTokenTtlSeconds: 1,
            requestObjectSigningAlg: 'one',
            jwksUri: 'one',
            jwksJson: 'one',
            version: 1,
        );
        $sourceEnabled = false;
        $targetEnabled = true;
        $source = $source->withEnabled($sourceEnabled);

        // @Act
        $target = $source->enable();

        // @Assert
        $this->assertEquals(false, $source->isEnabled());
        $this->assertEquals($targetEnabled, $target->isEnabled());
        $this->assertNotEquals($sourceEnabled, $target->isEnabled());
    }
